describe('Logout from Side Menu', () => {
  beforeEach(() => {
    cy.visit('/');
    cy.login('standard_user', 'secret_sauce');
  });

  it('should log out successfully and return to login page', () => {
    // Verify user is signed in
    cy.get('[data-testid="user-name"]').should('be.visible').should('contain', 'standard_user');
    cy.get('[data-testid="user-email"]').should('be.visible').should('contain', 'standard_user@example.com');

    // Click burger menu button to open side menu
    cy.get('[data-testid="react-burger-menu-btn"]').click();
    cy.get('[data-testid="sidebar-menu"]').should('be.visible');

    // Click logout link
    cy.get('[data-testid="logout_sidebar_link"]').click();

    // Verify user is redirected to login page
    cy.url().should('include', '/login');

    // Verify login button is visible again
    cy.get('[data-testid="login-button"]').should('be.visible');

    // Verify session has ended (e.g., no user data is displayed)
    cy.get('[data-testid="user-name"]').should('not.exist');
    cy.get('[data-testid="user-email"]').should('not.exist');
  });

  it('should handle logout when user is already logged out', () => {
    // Verify user is already logged out
    cy.get('[data-testid="user-name"]').should('not.exist');
    cy.get('[data-testid="user-email"]').should('not.exist');

    // Click burger menu button to open side menu
    cy.get('[data-testid="react-burger-menu-btn"]').click();
    cy.get('[data-testid="sidebar-menu"]').should('be.visible');

    // Click logout link
    cy.get('[data-testid="logout_sidebar_link"]').click();

    // Verify user is redirected to login page
    cy.url().should('include', '/login');

    // Verify login button is visible again
    cy.get('[data-testid="login-button"]').should('be.visible');

    // Verify session has ended (e.g., no user data is displayed)
    cy.get('[data-testid="user-name"]').should('not.exist');
    cy.get('[data-testid="user-email"]').should('not.exist');
  });
});
